 length of a message

When looking at the data in a USB urb, the actual_length is the size of
the buffer passed to the driver, not the transfer_buffer_length which is
set by the driver as the max size of the buffer.

When parsing the messages in ems_usb_read_bulk_callback() properly check
the size both at the beginning of parsing the message to make sure it is
big enough for the expected structure, and at the end of the message to
make sure we don't overflow past the end of the buffer for the next
message.

Cc: Vincent Mailhol <mailhol@kernel.org>
Cc: Marc Kleine-Budde <mkl@pengutronix.de>
Cc: stable@kernel.org
Assisted-by: gkh_clanker_2000
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Link: https://patch.msgid.link/2026022316-answering-strainer-a5db@gregkh
Fixes: 702171adeed3 ("ems_usb: Added support for EMS CPC-USB/ARM7 CAN/USB interface")
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
The bug is caused by using `urb->transfer_buffer_length` (the maximum buffer size allocated by the driver) instead of `urb->actual_length` (the actual number of bytes received in the URB) to validate message boundaries while parsing multiple CAN messages in `ems_usb_read_bulk_callback()`. This incorrect length check allows the parser to read beyond the valid received data, potentially causing memory corruption or access to uninitialized memory when multiple messages are bundled in a single URB.

Here is the patch:
  */
 static void ems_usb_read_bulk_callback(struct urb *urb)
 {
 	struct ems_usb *dev = urb->context;
 	struct net_device *netdev;
 	int retval;

 	netdev = dev->netdev;

 	if (!netif_device_present(netdev))
 		return;

 	switch (urb->status) {
 	case 0: /* success */
 		break;

 	case -ENOENT:
 		return;

 	default:
 		netdev_info(netdev, "Rx URB aborted (%d)\n", urb->status);
 		goto resubmit_urb;
 	}

 	if (urb->actual_length > CPC_HEADER_SIZE) {
 		struct ems_cpc_msg *msg;
 		u8 *ibuf = urb->transfer_buffer;
 		u8 msg_count, start;

 		msg_count = ibuf[0] & ~0x80;

 		start = CPC_HEADER_SIZE;

 		while (msg_count) {
+			if (start + CPC_MSG_HEADER_LEN > urb->actual_length) {
+				netdev_err(netdev, "format error\n");
+				break;
+			}
+
 			msg = (struct ems_cpc_msg *)&ibuf[start];

 			switch (msg->type) {
 			case CPC_MSG_TYPE_CAN_STATE:
 				/* Process CAN state changes */
 				ems_usb_rx_err(dev, msg);
 				break;

 			case CPC_MSG_TYPE_CAN_FRAME:
 			case CPC_MSG_TYPE_EXT_CAN_FRAME:
 			case CPC_MSG_TYPE_RTR_FRAME:
 			case CPC_MSG_TYPE_EXT_RTR_FRAME:
 				ems_usb_rx_can_msg(dev, msg);
 				break;

 			case CPC_MSG_TYPE_CAN_FRAME_ERROR:
 				/* Process errorframe */
 				ems_usb_rx_err(dev, msg);
 				break;

 			case CPC_MSG_TYPE_OVERRUN:
 				/* Message lost while receiving */
 				ems_usb_rx_err(dev, msg);
 				break;
 			}

 			start += CPC_MSG_HEADER_LEN + msg->length;
 			msg_count--;

-			if (start > urb->transfer_buffer_length) {
+			if (start > urb->actual_length) {
 				netdev_err(netdev, "format error\n");
 				break;
 			}
 		}
 	}

 resubmit_urb:
 	usb_fill_bulk_urb(urb, dev->udev, usb_rcvbulkpipe(dev->udev, 2),
 			  urb->transfer_buffer, RX_BUFFER_SIZE,
 			  ems_usb_read_bulk_callback, dev);

 	usb_anchor_urb(urb, &dev->rx_submitted);

 	retval = usb_submit_urb(urb, GFP_ATOMIC);
 	if (!retval)
 		return;

 	usb_unanchor_urb(urb);

 	if (retval == -ENODEV)
 		netif_device_detach(netdev);
 	else
 		netdev_err(netdev,
 			   "failed resubmitting read bulk urb: %d\n", retval);
 }



